cssCode:
.origami-wrap { perspective: 1000px; display: flex; flex-direction: column; align-items: center; }
.origami-btn {
  width: 200px; padding: 15px; background: #6c63ff; color: #fff;
  text-align: center; font-weight: bold; font-family: sans-serif;
  border-radius: 10px; cursor: pointer; z-index: 10; position: relative;
  box-shadow: 0 5px 15px rgba(108,99,255,0.4);
}
.origami-panel {
  width: 180px; padding: 15px; background: #2a2a4a; color: #fff;
  text-align: center; font-family: sans-serif;
  transform-origin: top; transform: rotateX(-90deg);
  opacity: 0; transition: transform 0.5s ease, opacity 0.3s ease;
  border-bottom-left-radius: 10px; border-bottom-right-radius: 10px;
  box-shadow: 0 10px 20px rgba(0,0,0,0.5); margin-top: -5px;
}
.origami-wrap.open .origami-panel {
  transform: rotateX(0deg); opacity: 1;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'origami-wrap';

const btn = document.createElement('div');
btn.className = 'origami-btn';
btn.innerText = 'TAP TO UNFOLD ▾';

const panel = document.createElement('div');
panel.className = 'origami-panel';
panel.innerHTML = '<div style="padding:10px; border-bottom:1px solid #444;">Profile</div><div style="padding:10px;">Settings</div>';

wrap.appendChild(btn);
wrap.appendChild(panel);
c.appendChild(wrap);

btn.addEventListener('click', () => {
  wrap.classList.toggle('open');
});
